from typing import Generic, List, TypeVar

T = TypeVar("T")


@dataclass
class Page(Generic[T]):
    items: List[T]
    page: int
    total_pages: int


def paginate(items: List[T], page: int, per_page: int = 20) -> Page[T]:
    """Return one page of items. Pages are 1-indexed."""
    if page < 1 or per_page < 1:
        raise ValueError("page and per_page must be positive")

    total_pages = max(1, -(-len(items) // per_page))  # ceiling division
    start = page * per_page
    end = start + per_page

    return Page(items=items[start:end], page=page, total_pages=total_pages)

