export class OutOfStockError extends Error {}

/**
 * Reserve `quantity` units for a checkout. Runs concurrently for every
 * checkout request, so it must never oversell.
 */
export async function reserveStock(productId: string, quantity: number): Promise<void> {
  if (!Number.isInteger(quantity) || quantity <= 0) {
    throw new RangeError("quantity must be a positive integer");
  }

  const { rows } = await pool.query("SELECT stock FROM products WHERE id = $1", [productId]);
  if (rows.length === 0) throw new Error(`Unknown product ${productId}`);

  const stock: number = rows[0].stock;
  if (stock < quantity) throw new OutOfStockError(`Only ${stock} left`);

  await pool.query("UPDATE products SET stock = $1 WHERE id = $2", [stock - quantity, productId]);
}

