const FALLBACK = "https://app.example.com/dashboard";

/**
 * Where to send the user after login. Only our own sites (example.com and
 * its subdomains) are allowed, to prevent open redirects.
 */
export function safeRedirectTarget(next: string | null): string {
  if (!next) return FALLBACK;

  let url: URL;
  try {
    url = new URL(next);
  } catch {
    return FALLBACK;
  }

  const isOurs = url.hostname.endsWith(ALLOWED_DOMAIN);
  if (url.protocol !== "https:" || !isOurs) {
    return FALLBACK;
  }
  return url.toString();
}

