-- Transfer funds between accounts. Called concurrently by the API,
-- at the default READ COMMITTED isolation level.
CREATE FUNCTION transfer(p_from BIGINT, p_to BIGINT, p_amount NUMERIC)
RETURNS VOID AS $$
DECLARE
    v_balance NUMERIC;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'amount must be positive';
    END IF;

    SELECT balance INTO v_balance FROM accounts WHERE id = p_from;
    IF v_balance IS NULL THEN
        RAISE EXCEPTION 'account % not found', p_from;
    ELSIF v_balance < p_amount THEN
        RAISE EXCEPTION 'insufficient funds';
    END IF;

    UPDATE accounts SET balance = v_balance - p_amount WHERE id = p_from;
    UPDATE accounts SET balance = balance + p_amount WHERE id = p_to;
END;
$$ LANGUAGE plpgsql;

