import (
	"net/http"
	"sync"
)

// CheckAll requests every URL concurrently and returns the ones that are down.
func CheckAll(client *http.Client, urls []string) []string {
	var wg sync.WaitGroup
	var down []string
	for _, u := range urls {
		wg.Add(1)
		go func(url string) {
			defer wg.Done()
			resp, err := client.Get(url)
			if err == nil {
				resp.Body.Close()
			}
			if err != nil || resp.StatusCode >= 500 {
				down = append(down, url)
			}
		}(u)
	}
	wg.Wait()
	return down
}

